<template><div class="space-y-4"><el-input v-model="target" type="datetime-local"/><div class="grid grid-cols-4 gap-3 text-center"><div v-for="item in display" :key="item.label" class="rounded-xl bg-blue-50 p-4 dark:bg-blue-900/30"><b class="block text-2xl text-blue-600 dark:text-blue-400">{{ item.value }}</b><span class="text-xs text-gray-500">{{ item.label }}</span></div></div><el-button size="small" type="primary" @click="start">开始倒计时</el-button><el-button size="small" @click="stop">停止</el-button></div></template>
<script setup lang="ts">import { computed, onUnmounted, ref } from 'vue';const target=ref('');const left=ref(0);let timer:number|undefined;const display=computed(()=>{let s=Math.max(0,Math.floor(left.value/1000));return [{label:'天',value:Math.floor(s/86400)},{label:'时',value:String(Math.floor(s%86400/3600)).padStart(2,'0')},{label:'分',value:String(Math.floor(s%3600/60)).padStart(2,'0')},{label:'秒',value:String(s%60).padStart(2,'0')}]});const start=()=>{stop();if(!target.value)return;const tick=()=>{left.value=new Date(target.value).getTime()-Date.now();if(left.value<=0)stop()};tick();timer=window.setInterval(tick,1000)};const stop=()=>{if(timer)window.clearInterval(timer);timer=undefined};onUnmounted(stop)</script>
